import{_ as o,l as i,o as e,c as R,v as r,p as s,x as t,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"RRIP 与死块预测","description":"","frontmatter":{"title":"RRIP 与死块预测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rrip-dead-block.md","filePath":"cs/rrip-dead-block.md","lastUpdated":1789023840000}'),c={name:"cs/rrip-dead-block.md"};function P(E,a,h,B,_,m){const l=i("Mermaid");return e(),R("div",null,[a[1]||(a[1]=r('<h1 id="rrip-与死块预测" tabindex="-1">RRIP 与死块预测 <a class="header-anchor" href="#rrip-与死块预测" aria-label="Permalink to &quot;RRIP 与死块预测&quot;">​</a></h1><div class="epigraph"><p>新填入的块不一定立刻还要再用；把它插在「较远再引用」而不是 MRU，扫描就冲不掉真正的热块。死块则是填进来之后再也不会命中的行。</p><footer>—— 据 Jaleel et al., High Performance Cache Replacement Using Re-Reference Interval Prediction, ISCA 2010 整理</footer></div><p><a href="/cs/lru-plru">上一课</a> 的 LRU 把新块当 MRU。扫描或一次性流会把热工作集冲光，然后自身也不再命中——典型的容量/冲突混合痛点。本课不重做 PLRU 树。缺口是<strong>用再引用间隔预测（RRIP）改变插入位置</strong>，并点名死块：占着 SRAM 却零命中。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>L2/L3 上看流式缺失：每个块用一次。LRU 让它们从 MRU 走到 LRU 的路上挤走循环核。若新块插入时就当成「很久以后才再用」（甚至「可能再也不用」），热块可以留住。缺口不是加路，而是<strong>给每路一个饱和的再引用预测值，替换踢预测最远的</strong>。</p><p><span class="marginnote">Jaleel 等的 SRRIP：若干位 RRPV，插入取中间值，命中置 0（近再引用），替换踢 RRPV 最大者并老化其他。BRRIP 用双峰插入对付扫描。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每路存 RRPV。缺失：在 RRPV 最大的路里挑牺牲者；若没有最大，把所有 RRPV 加一再找。命中：该路 RRPV ← 0。插入：SRRIP 用 \\(2^k-2\\) 一类的中间值；检测到扫描则用 BRRIP 以高概率插成「远」。</p>',8)),(e(),s(p,null,{default:t(()=>[d(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%EF%BC%9A%E4%B8%AD%E9%97%B4%E6%88%96%E8%BF%9C%20RRPV%22%5D%20--%3E%20SET%5B%22%E7%BB%84%E5%86%85%E5%90%84%E8%B7%AF%22%5D%0A%20%20HIT%5B%22%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20NEAR%5B%22RRPV%20%E7%BD%AE%E8%BF%91%22%5D%0A%20%20MISS%5B%22%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20VIC%5B%22%E8%B8%A2%20RRPV%20%E6%9C%80%E8%BF%9C%22%5D%0A%20%20VIC%20--%3E%20AGE%5B%22%E5%BF%85%E8%A6%81%E6%97%B6%E5%85%A8%E4%BD%93%E8%80%81%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>死块预测（DBP）：用 PC 或踪迹学习「这块填完不会再命中」，插入即标为可替换或根本不填 L3。它与 RRIP 互补：一个改间隔，一个预测零命中。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LLC 的命中率对替换极敏感，因为缺失要去 DRAM。<a href="/cs/cpi-amdahl">CPI</a> 的访存项在这里被替换策略移动。L1 仍常用 LRU/PLRU：命中延迟更重要，扫描相对少。预取块的插入 RRPV 往往更「远」，以免污染，与后课预取污染是同一旋钮。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有学术替换器（DRRIP、SHIP、Hawkeye）列成菜单。也不把死块预测做成必须实现的单元。VIPT 的索引/标签拆分是下一课，与 RRPV 无关但决定「组」怎么找。</p><p>后课默认：LLC 插入不必是 MRU；扫描用远插入保护热块。组的索引用虚还是实用，下一课 VIPT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RRIP 用再引用间隔而不是「刚用过 = 最热」来替换。</li><li>死块预测针对填入后零命中的行。</li><li>虚索引物理标签是下一课的时序技巧。</li><li>出处：Jaleel et al., <em>ISCA</em>, 2010。</li></ul>',8))])}const u=o(c,[["render",P]]);export{I as __pageData,u as default};
